SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET CONCAT_NULL_YIELDS_NULL ON; SET ARITHABORT ON; SET NUMERIC_ROUNDABORT OFF;
IF OBJECT_ID(N'dbo.settings',N'U') IS NULL CREATE TABLE dbo.settings(id int NOT NULL PRIMARY KEY CHECK(id=1),name nvarchar(60),institution nvarchar(150),semester int NOT NULL);
IF OBJECT_ID(N'dbo.semesters',N'U') IS NULL CREATE TABLE dbo.semesters(id int NOT NULL PRIMARY KEY,name nvarchar(60) NOT NULL);
IF OBJECT_ID(N'dbo.users',N'U') IS NULL CREATE TABLE dbo.users(id nvarchar(36) NOT NULL PRIMARY KEY,name nvarchar(80) NOT NULL,email nvarchar(200) NOT NULL UNIQUE,password nvarchar(256) NOT NULL,role nvarchar(16) NOT NULL DEFAULT 'pending' CHECK(role IN('admin','member','pending','blocked')),created nvarchar(24) NOT NULL,semester int REFERENCES dbo.semesters(id));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'users_one_admin' AND object_id=OBJECT_ID(N'dbo.users')) CREATE UNIQUE INDEX users_one_admin ON dbo.users(role) WHERE role='admin';
IF OBJECT_ID(N'dbo.sessions',N'U') IS NULL CREATE TABLE dbo.sessions(token nvarchar(64) NOT NULL PRIMARY KEY,userId nvarchar(36) NOT NULL REFERENCES dbo.users(id) ON DELETE CASCADE,expires bigint NOT NULL);
IF OBJECT_ID(N'dbo.auth_failures',N'U') IS NULL CREATE TABLE dbo.auth_failures([identity] nvarchar(64) NOT NULL PRIMARY KEY,attempts int NOT NULL,[reset] bigint NOT NULL);
IF OBJECT_ID(N'dbo.subjects',N'U') IS NULL CREATE TABLE dbo.subjects(id nvarchar(36) NOT NULL PRIMARY KEY,semester int REFERENCES dbo.semesters(id),name nvarchar(100) NOT NULL,code nvarchar(30) NOT NULL DEFAULT '',description nvarchar(300) NOT NULL DEFAULT '',color nvarchar(20) NOT NULL DEFAULT 'sage');
IF OBJECT_ID(N'dbo.notes',N'U') IS NULL CREATE TABLE dbo.notes(id nvarchar(36) NOT NULL PRIMARY KEY,subjectId nvarchar(36) NOT NULL REFERENCES dbo.subjects(id) ON DELETE CASCADE,title nvarchar(150) NOT NULL,content nvarchar(max) NOT NULL DEFAULT '',filename nvarchar(100),originalName nvarchar(200),mime nvarchar(150),size int NOT NULL DEFAULT 0,authorId nvarchar(36) NOT NULL REFERENCES dbo.users(id),created nvarchar(24) NOT NULL);
IF OBJECT_ID(N'dbo.notices',N'U') IS NULL CREATE TABLE dbo.notices(id nvarchar(36) NOT NULL PRIMARY KEY,semester int REFERENCES dbo.semesters(id),title nvarchar(150) NOT NULL,content nvarchar(max) NOT NULL,category nvarchar(30) NOT NULL,pinned bit NOT NULL DEFAULT 0,authorId nvarchar(36) REFERENCES dbo.users(id),created nvarchar(24) NOT NULL);
IF OBJECT_ID(N'dbo.threads',N'U') IS NULL CREATE TABLE dbo.threads(id nvarchar(36) NOT NULL PRIMARY KEY,semester int REFERENCES dbo.semesters(id),title nvarchar(150) NOT NULL,content nvarchar(max) NOT NULL,authorId nvarchar(36) REFERENCES dbo.users(id),created nvarchar(24) NOT NULL);
IF OBJECT_ID(N'dbo.replies',N'U') IS NULL CREATE TABLE dbo.replies(id nvarchar(36) NOT NULL PRIMARY KEY,threadId nvarchar(36) REFERENCES dbo.threads(id) ON DELETE CASCADE,content nvarchar(max) NOT NULL,authorId nvarchar(36) REFERENCES dbo.users(id),created nvarchar(24) NOT NULL);
IF OBJECT_ID(N'dbo.events',N'U') IS NULL CREATE TABLE dbo.events(id nvarchar(36) NOT NULL PRIMARY KEY,semester int REFERENCES dbo.semesters(id),title nvarchar(150) NOT NULL,description nvarchar(2000) NOT NULL DEFAULT '',date nvarchar(16) NOT NULL,kind nvarchar(30) NOT NULL,location nvarchar(150) NOT NULL DEFAULT '',authorId nvarchar(36) REFERENCES dbo.users(id));
IF OBJECT_ID(N'dbo.routines',N'U') IS NULL CREATE TABLE dbo.routines(semester int NOT NULL REFERENCES dbo.semesters(id),kind nvarchar(10) NOT NULL CHECK(kind IN('class','exam')),content nvarchar(max) NOT NULL,revision int NOT NULL CHECK(revision>0),updated nvarchar(24) NOT NULL,PRIMARY KEY(semester,kind));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'subjects_semester' AND object_id=OBJECT_ID(N'dbo.subjects')) CREATE INDEX subjects_semester ON dbo.subjects(semester);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'notes_subject_created' AND object_id=OBJECT_ID(N'dbo.notes')) CREATE INDEX notes_subject_created ON dbo.notes(subjectId,created DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'sessions_user_expiry' AND object_id=OBJECT_ID(N'dbo.sessions')) CREATE INDEX sessions_user_expiry ON dbo.sessions(userId,expires DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'replies_thread' AND object_id=OBJECT_ID(N'dbo.replies')) CREATE INDEX replies_thread ON dbo.replies(threadId);
